def test_prompt_on_validate_error_no_markup():
    # Mock console that cannot render markup
    class MockConsole:
        def can_render_markup(self) -> bool:
            return False
        def input(self, prompt: str, password: bool = False, stream: io.TextIO = None) -> str:
            return "invalid"

    mock_console = MockConsole()
    prompt_base = IntPrompt()

    # Test the hook directly
    error_message = prompt_base.on_validate_error("This is a test error message")

    expected_message = "Error: This is a test error message. Please ensure markup is enabled in your console."
    assert error_message == expected_message

def test_prompt_on_validate_error_with_markup():
    # Mock console that can render markup
    class MockConsole:
        def can_render_markup(self) -> bool:
            return True
        def input(self, prompt: str, password: bool = False, stream: io.TextIO = None) -> str:
            return "invalid"

    mock_console = MockConsole()
    prompt_base = IntPrompt()

    # Test the hook directly
    error_message = prompt_base.on_validate_error("This is a test error message")

    assert error_message == "This is a test error message"
